1	#!/usr/bin/env node
2	import fs from 'node:fs/promises';
3	import path from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { validateSpec } from './gate/validate.js';
6	import { renderJson, renderText } from './gate/report.js';
7	import { verdictFrom } from './gate/schema.js';
8	import { draftGateSection, smartReview } from './pipeline/agent.js';
9	
10	const TEMPLATE_PATH = fileURLToPath(new URL('../assets/rai-spec-template.md', import.meta.url));
11	
12	const CI_WORKFLOW = `name: Responsible AI Gate
13	on:
14	  pull_request:
15	  push:
16	    branches: [main]
17	jobs:
18	  rai-gate:
19	    runs-on: ubuntu-latest
20	    steps:
21	      - uses: actions/checkout@v4
22	      - uses: actions/setup-node@v4
23	        with:
24	          node-version: '20'
25	      # Blocks the build until every Responsible AI Gate check in the spec is answered.
26	      - run: npx frai-gate check FRAI-SPEC.md
27	`;
28	
29	const HELP = `frai-gate - the FRAI Gate: a Responsible AI Gate for specs
30	
31	Usage:
32	  frai-gate init [--out <file>] [--ci]   Drop the RAI spec template into the repo (default: FRAI-SPEC.md);
33	                                         --ci also writes .github/workflows/rai-gate.yml so the gate
34	                                         runs on every PR
35	  frai-gate check <spec.md> [options]    Validate the spec's Responsible AI Gate
36	      --smart                            Add an AI quality review of the gate answers (Claude Agent SDK)
37	      --json                             Machine-readable output
38	  frai-gate draft [--out <file>] [--print]
39	                                         Scan this repo with a read-only agent and draft a filled-in
40	                                         gate section grounded in the code (default out: rai-gate-draft.md)
41	
42	Exit codes: 0 = PASS/WARN, 1 = BLOCK, 2 = usage/error.
43	The smart commands (draft, check --smart) use the Claude Agent SDK and need Claude Code
44	authentication or ANTHROPIC_API_KEY. Model override: FRAI_GATE_MODEL (default claude-opus-5).`;
45	
46	interface Args {
47	  command: string | undefined;
48	  positional: string[];
49	  flags: Map<string, string | true>;
50	}
51	
52	function parseArgs(argv: string[]): Args {
53	  const [command, ...rest] = argv;
54	  const positional: string[] = [];
55	  const flags = new Map<string, string | true>();
56	  for (let i = 0; i < rest.length; i += 1) {
57	    const arg = rest[i];
58	    if (arg.startsWith('--')) {
59	      const name = arg.slice(2);
60	      const next = rest[i + 1];
61	      if (next !== undefined && !next.startsWith('--') && ['out', 'spec'].includes(name)) {
62	        flags.set(name, next);
63	        i += 1;
64	      } else {
65	        flags.set(name, true);
66	      }
67	    } else {
68	      positional.push(arg);
69	    }
70	  }
71	  return { command, positional, flags };
72	}
73	
74	async function cmdInit(args: Args): Promise<number> {
75	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'FRAI-SPEC.md';
76	  const target = path.resolve(process.cwd(), out);
77	  try {
78	    await fs.access(target);
79	    console.error(`Refusing to overwrite existing file: ${out}`);
80	    return 2;
81	  } catch {
82	    // does not exist - good
83	  }
84	  const template = await fs.readFile(TEMPLATE_PATH, 'utf8');
85	  await fs.writeFile(target, template);
86	  console.log(`Created ${out}. Fill in every FRAI Gate field, then run: frai-gate check ${out}`);
87	  if (args.flags.has('ci')) {
88	    const wfDir = path.resolve(process.cwd(), '.github/workflows');
89	    const wfPath = path.join(wfDir, 'rai-gate.yml');
90	    try {
91	      await fs.access(wfPath);
92	      console.error('Skipping CI workflow: .github/workflows/rai-gate.yml already exists.');
93	    } catch {
94	      await fs.mkdir(wfDir, { recursive: true });
95	      const workflow =
96	        out === 'FRAI-SPEC.md' ? CI_WORKFLOW : CI_WORKFLOW.replace('FRAI-SPEC.md', out);
97	      await fs.writeFile(wfPath, workflow);
98	      console.log('Created .github/workflows/rai-gate.yml - the gate now runs on every PR.');
99	    }
100	  }
101	  return 0;
102	}
103	
104	async function cmdCheck(args: Args): Promise<number> {
105	  const specPath = args.positional[0];
106	  if (!specPath) {
107	    console.error('Usage: frai-gate check <spec.md> [--smart] [--json]');
108	    return 2;
109	  }
110	  const markdown = await fs.readFile(path.resolve(process.cwd(), specPath), 'utf8');
111	  const result = validateSpec(markdown);
112	
113	  if (args.flags.has('smart') && result.gateSection) {
114	    const agentFindings = await smartReview(markdown, process.cwd());
115	    result.findings.push(...agentFindings);
116	    result.verdict = verdictFrom(result.findings);
117	  } else if (args.flags.has('smart') && !result.gateSection) {
118	    console.error('Skipping smart review: no gate section to review.');
119	  }
120	
121	  console.log(args.flags.has('json') ? renderJson(result, specPath) : renderText(result, specPath));
122	  return result.verdict === 'BLOCK' ? 1 : 0;
123	}
124	
125	async function cmdDraft(args: Args): Promise<number> {
126	  const section = await draftGateSection(process.cwd());
127	  if (args.flags.has('print')) {
128	    console.log(section);
129	    return 0;
130	  }
131	  const out = typeof args.flags.get('out') === 'string' ? (args.flags.get('out') as string) : 'rai-gate-draft.md';
132	  await fs.writeFile(path.resolve(process.cwd(), out), `${section}\n`);
133	  console.log(`Drafted gate section written to ${out}.`);
134	  console.log('Review it, resolve every "NEEDS HUMAN INPUT" item, paste it into your spec, then run: frai-gate check <spec.md>');
135	  return 0;
136	}
137	
138	async function main(): Promise<void> {
139	  const args = parseArgs(process.argv.slice(2));
140	  let code = 0;
141	  switch (args.command) {
142	    case 'init':
143	      code = await cmdInit(args);
144	      break;
145	    case 'check':
146	      code = await cmdCheck(args);
147	      break;
148	    case 'draft':
149	      code = await cmdDraft(args);
150	      break;
151	    case undefined:
152	    case 'help':
153	    case '--help':
154	      console.log(HELP);
155	      break;
156	    default:
157	      console.error(`Unknown command: ${args.command}\n`);
158	      console.log(HELP);
159	      code = 2;
160	  }
161	  process.exitCode = code;
162	}
163	
164	main().catch((error: unknown) => {
165	  console.error(error instanceof Error ? error.message : String(error));
166	  process.exitCode = 2;
167	});
