1	import { Finding, GateResult } from './schema.js';
2	
3	const VERDICT_ICON: Record<GateResult['verdict'], string> = {
4	  PASS: '✅',
5	  WARN: '⚠️',
6	  BLOCK: '⛔'
7	};
8	
9	function line(finding: Finding): string {
10	  const icon = finding.severity === 'block' ? '⛔' : '⚠️';
11	  const tag = finding.source === 'agent' ? ' (smart review)' : '';
12	  return `${icon} [${finding.checkId}]${tag} ${finding.message}`;
13	}
14	
15	export function renderText(result: GateResult, specPath: string): string {
16	  const out: string[] = [];
17	  out.push(`FRAI Gate - ${specPath}`);
18	  out.push(`Verdict: ${VERDICT_ICON[result.verdict]} ${result.verdict}`);
19	  if (result.tier) out.push(`Risk tier: ${result.tier}`);
20	  if (result.findings.length === 0) {
21	    out.push('All seven gate checks answered. Clear to implement.');
22	  } else {
23	    out.push('');
24	    for (const finding of result.findings) out.push(line(finding));
25	    out.push('');
26	    if (result.verdict === 'BLOCK') {
27	      out.push('BLOCK: fix the items above before implementation starts.');
28	    } else if (result.verdict === 'WARN') {
29	      out.push('WARN: the gate passes structurally, but tighten the flagged answers.');
30	    }
31	  }
32	  return out.join('\n');
33	}
34	
35	export function renderJson(result: GateResult, specPath: string): string {
36	  return JSON.stringify(
37	    {
38	      spec: specPath,
39	      verdict: result.verdict,
40	      tier: result.tier,
41	      findings: result.findings
42	    },
43	    null,
44	    2
45	  );
46	}
