77	  try {
78	    await fs.access(target);
79	    console.error(`Refusing to overwrite existing file: ${out}`);
80	    return 2;
81	  } catch {
82	    // does not exist - good
83	  }
84	  const template = await fs.readFile(TEMPLATE_PATH, 'utf8');
85	  await fs.writeFile(target, template);
86	  console.log(`Created ${out}. Fill in every FRAI Gate field, then run: frai-gate check ${out}`);
87	  if (args.flags.has('ci')) {
88	    const wfDir = path.resolve(process.cwd(), '.github/workflows');
89	    const wfPath = path.join(wfDir, 'rai-gate.yml');
90	    try {
91	      await fs.access(wfPath);
92	      console.error('Skipping CI workflow: .github/workflows/rai-gate.yml already exists.');
93	    } catch {
94	      await fs.mkdir(wfDir, { recursive: true });
95	      const workflow =
96	        out === 'FRAI-SPEC.md' ? CI_WORKFLOW : CI_WORKFLOW.replace('FRAI-SPEC.md', out);
