  const args = parseArgs(process.argv.slice(2));
  let code = 0;
  switch (args.command) {
    case 'init':
      code = await cmdInit(args);
      break;
    case 'check':
      code = await cmdCheck(args);
      break;
    case 'draft':
      code = await cmdDraft(args);
